{
  "name": "payroll-automation",
  "private": true,
  "version": "1.0.0",
  "description": "Automated payroll processing for a part-time and incentive-based workforce",
  "scripts": {
    "dev": "concurrently -n backend,frontend -c blue,magenta \"npm --prefix backend run dev\" \"npm --prefix frontend run dev\"",
    "dev:backend": "npm --prefix backend run dev",
    "dev:frontend": "npm --prefix frontend run dev",
    "start": "npm --prefix backend run start",
    "build": "npm --prefix frontend run build",
    "test": "npm --prefix backend run test",
    "test:coverage": "npm --prefix backend run test:coverage",
    "lint": "npm --prefix frontend run lint"
  },
  "devDependencies": {
    "concurrently": "^9.2.0"
  },
  "engines": {
    "node": ">=20"
  }
}

