1	import { useState } from "react";
2	import { useNavigate } from "react-router-dom";
3	
4	function LoginPage() {
5	  const navigate = useNavigate();
6	  const [email, setEmail] = useState("");
7	  const [password, setPassword] = useState("");
8	  const [message, setMessage] = useState("");
9	
10	  function signIn(event) {
11	    event.preventDefault();
12	    if (!email.trim() || !password) {
13	      setMessage("Enter your email address and password to continue.");
14	      return;
15	    }
16	    navigate("/");
17	  }
18	
19	  return <main className="login-page">
20	    <style>{styles}</style>
21	    <section className="login-brand-panel">
22	      <div className="brand-orb" /><div className="brand-rings" />
23	      <div className="brand-copy"><p>PAYROLL AUTOMATION SYSTEM</p><span /><h1>Simple, secure<br />payroll management.</h1><div>Manage the payroll workflow from roster data through approval in one place.</div></div>
24	      <footer>Payroll Automation System<br />Version 1.0</footer>
25	    </section>
26	    <section className="login-form-panel">
27	      <form className="login-card" onSubmit={signIn}>
28	        <header><h2>Welcome back</h2><p>Sign in to continue to your account.</p></header>
29	        {message && <div className="login-message">{message}</div>}
30	        <label>Email address<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" placeholder="Enter your email" autoComplete="email" /></label>
31	        <label>Password<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" placeholder="Enter your password" autoComplete="current-password" /></label>
