.app-shell {
  display: flex;
  min-height: 100vh;
  background: #f4f5f7;
  font-family: Inter, "Segoe UI", Roboto, Arial, sans-serif;
}

.app-sidebar {
  width: 250px;
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  color: #fff;
  background: linear-gradient(165deg, #7a0000 0%, #560000 60%, #3a0000 100%);
  transition: width 0.18s ease, transform 0.18s ease;
}

.app-sidebar.collapsed {
  width: 76px;
}

.sidebar-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 22px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
  overflow: hidden;
}

.brand-mark {
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.16);
  font-weight: 800;
  font-size: 0.85rem;
  letter-spacing: 0.02em;
}

.sidebar-brand strong {
  display: block;
  font-size: 1rem;
  letter-spacing: 0.03em;
  white-space: nowrap;
}

.sidebar-brand small {
  display: block;
  margin-top: 2px;
  color: rgba(255, 255, 255, 0.72);
  font-size: 0.66rem;
  white-space: nowrap;
}

.app-sidebar.collapsed .sidebar-brand strong,
.app-sidebar.collapsed .sidebar-brand small,
.app-sidebar.collapsed .sidebar-nav span,
.app-sidebar.collapsed .sidebar-footer span {
  display: none;
}

.sidebar-nav {
  flex: 1;
  padding: 14px 12px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  overflow-y: auto;
  overflow-x: hidden;
}

.sidebar-nav a {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 12px;
  border-radius: 9px;
  color: rgba(255, 255, 255, 0.82);
  text-decoration: none;
  font-size: 0.87rem;
  font-weight: 650;
  white-space: nowrap;
}

.sidebar-nav a svg {
  flex: 0 0 auto;
}

.sidebar-nav a:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.sidebar-nav a.active {
  background: #fff;
  color: #7a0000;
}

.sidebar-footer {
  padding: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.14);
}

.sidebar-footer button {
